cat > check.py << 'EOF'
import numpy as np
els=[]; P=[]
for i,l in enumerate(open('opt.xyz').read().splitlines()):
    if i<2: continue
    s=l.split(); els.append(s[0]); P.append([float(s[1]),float(s[2]),float(s[3])])
P=np.array(P)
radii={'H':0.31,'C':0.76,'O':0.66,'I':1.33}
n=len(els)
def bond(i,j):
    return np.linalg.norm(P[i]-P[j]) < (radii[els[i]]+radii[els[j]])*1.25
from collections import defaultdict
adj=defaultdict(list)
for i in range(n):
    for j in range(i+1,n):
        if bond(i,j):
            adj[i].append(j); adj[j].append(i)
# report for I and O and ring connectivity
for i in range(n):
    if els[i] in ('I','O'):
        print(els[i], i, '->', [(els[j],j,round(np.linalg.norm(P[i]-P[j]),3)) for j in adj[i]])
# methyl groups: carbons with 3 H
print('--- methyl/ring C summary ---')
for i in range(n):
    if els[i]=='C':
        hs=[j for j in adj[i] if els[j]=='H']
        heavy=[j for j in adj[i] if els[j]!='H']
        if len(hs)==3: print('METHYL C',i,'attached to',[(els[j],j) for j in heavy])
# biaryl bond: C-C between the two rings ~ find C with two ring C neighbors + one C neighbor that is ring of other
print('total atoms',n)
EOF
python3 check.py
